/* Physical products saved while `products.requires_shipping` defaulted to false (parts 78 to 160) are turned back to shipped, once: a row the product editor's create wrote without the shipping card (the card not mounted, a save that stopped part way, an import, an agent) sold with no address, no delivery and no shipping at checkout, so the order could not be fulfilled. Part 161 changed only the default; this changes the rows, one time only (it does nothing once part 168 is in storelib_applied_parts), so a seller who turns "This product is shipped" off after it ran keeps that choice. Before it has run, those products keep selling with no address. To see what it changed, run: select id, title from public.products where type = 'physical' and requires_shipping = true and updated_at >= (select applied_at from public.storelib_applied_parts where part = '168'); Needs parts 67 and 78. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.storelib_applied_parts') IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.storelib_applied_parts WHERE part = '168') AND EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'products' AND column_name = 'requires_shipping') THEN UPDATE public.products SET requires_shipping = true, updated_at = now() WHERE type = 'physical' AND requires_shipping = false; END IF; END $do$;
ALTER TABLE public.products ALTER COLUMN requires_shipping SET DEFAULT true;
notify pgrst, 'reload schema';
